8	import net.officefloor.plugin.variable.Out;
9	import org.springframework.samples.petclinic.mapper.OwnerMapper;
10	import org.springframework.samples.petclinic.model.Owner;
11	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
12	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
13	import org.springframework.web.bind.annotation.RequestBody;
14	
15	public class BuildOwner {
16	
17	    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
18	
19	    public void service(@RequestBody OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built,
20	            Out<Boolean> sharesHousehold) throws MissingOwnerFieldsException {
21	        sharesHousehold.set(Boolean.TRUE.equals(request.getSharesHousehold()));
22	        Map<String, String> required = new LinkedHashMap<>();
23	        required.put("firstName", request.getFirstName());
24	        required.put("lastName", request.getLastName());
25	        String address = AddressNormalizer.normalize(request.getAddress());
26	        required.put("address", address);
27	        required.put("city", request.getCity());
28	        required.put("telephone", request.getTelephone());
29	        List<String> missing = required.entrySet().stream()
30	                .filter(e -> e.getValue() == null || e.getValue().isBlank())
31	                .map(Map.Entry::getKey).toList();
32	        if (!missing.isEmpty()) {
33	            throw new MissingOwnerFieldsException(missing);
34	        }
35	        Owner owner = ownerMapper.toOwner(request);
36	        String telephone = toE164(owner.getTelephone());
37	        if (telephone == null) {
38	            throw new MissingOwnerFieldsException(List.of("telephone"));
39	        }
40	        owner.setTelephone(telephone);
41	        owner.setAddress(address);
42	        String email = owner.getEmail();
43	        if (email != null && !EMAIL.matcher(email).matches()) {
44	            throw new MissingOwnerFieldsException(List.of("email"));
45	        }
46	        built.set(owner);
47	    }
48	
49	    /**
50	     * Normalizes a raw telephone to E.164. A leading '+' keeps its country code;
51	     * otherwise '+61' is assumed and a single leading '0' is dropped. Spaces, dashes
52	     * and brackets are stripped. Returns null when the result is not 8..15 digits.
53	     */
54	    static String toE164(String raw) {
55	        String trimmed = raw.trim();
56	        String digits;
57	        if (trimmed.startsWith("+")) {
58	            digits = trimmed.substring(1).replaceAll("\\D", "");
59	        }
60	        else {
61	            String national = trimmed.replaceAll("\\D", "");
62	            digits = "61" + (national.startsWith("0") ? national.substring(1) : national);
63	        }
64	        return digits.length() >= 8 && digits.length() <= 15 ? "+" + digits : null;
65	    }
66	}
