7	/**
8	 * Assigns the owner's {@code customerCode} before {@link SaveOwner} runs, formatted
9	 * {@code <CITY3>-<LAST3>-<NNNN>}: the upper-cased first three letters of the city and of
10	 * the last name, then a per-city 4-digit sequence one greater than the number of owners
11	 * already in that city.
12	 */
13	public class AssignCustomerCode {
14	
15	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
16	        String city3 = prefix(owner.getCity());
17	        String last3 = prefix(owner.getLastName());
18	        int sequence = citySequence(owner.getCity(), ownerRepository);
19	        owner.setCustomerCode(String.format("%s-%s-%04d", city3, last3, sequence));
20	    }
21	
22	    private static String prefix(String value) {
23	        return value.substring(0, Math.min(3, value.length())).toUpperCase();
24	    }
25	
26	    private static int citySequence(String city, OwnerRepository ownerRepository) {
27	        return (int) ownerRepository.findAll().stream()
28	            .filter(o -> city.equalsIgnoreCase(o.getCity()))
29	            .count() + 1;
30	    }
31	}
